const tabId = 1148881640;
const viewInfo = await browserjs(tabId, () => {
  const s1 = window.phet.joist.sim.screens[1];
  const view = s1.view;

  // Find all children or nodes in view
  const findNodes = (node, depth = 0) => {
    if (depth > 5) return [];
    let res = [];
    if (node.children) {
      for (let child of node.children) {
        let label = child.constructor ? child.constructor.name : '';
        if (child.accessibleName) label += ` [${child.accessibleName}]`;
        if (child._text) label += ` "${child._text}"`;
        res.push({ depth, name: label, type: child.constructor ? child.constructor.name : null, visible: child.visible });
        res = res.concat(findNodes(child, depth + 1));
      }
    }
    return res;
  };

  return {
    childrenCount: view.children.length,
    viewChildren: view.children.map(c => ({
      name: c.constructor.name,
      visible: c.visible,
      bounds: c.bounds ? [c.bounds.minX, c.bounds.minY, c.bounds.maxX, c.bounds.maxY] : null
    }))
  };
});
console.log(JSON.stringify(viewInfo, null, 2));

const tabId = 1148881640;
const buttonDetails = await browserjs(tabId, () => {
  const s1 = window.phet.joist.sim.screens[1];
  // Let's find all buttons in scenery nodes
  const foundButtons = [];
  const walk = (node, path = '') => {
    if (!node) return;
    const currentPath = path ? `${path} -> ${node.constructor.name}` : node.constructor.name;
    // Check if it looks like a button
    if (node.constructor.name.toLowerCase().includes('button') || node.accessibleName || node.tagName === 'button' || node.phetioID) {
      foundButtons.push({
        name: node.constructor.name,
        accessibleName: node.accessibleName || null,
        innerContent: node.innerContent || null,
        phetioID: node.phetioID || null,
        path: currentPath,
        text: node.text || (node._text) || null
      });
    }
    if (node.children) {
      for (let c of node.children) {
        walk(c, currentPath);
      }
    }
  };
  walk(s1.view);
  return foundButtons;
});
console.log(JSON.stringify(buttonDetails, null, 2));

