const protonBtnInfo = await browserjs(tabId, () => {
  const s1 = window.phet.joist.sim.screens[1];
  let protonEmissionNode = null;

  const search = (node) => {
    if (!node) return;
    if (node.stringProperty && node.stringProperty.value.includes('Proton emission')) {
      protonEmissionNode = node;
      return;
    }
    if (node.children) {
      for (let c of node.children) {
        search(c);
        if (protonEmissionNode) return;
      }
    }
  };
  search(s1.view);

  if (!protonEmissionNode) return { found: false };

  // Find ancestors
  let curr = protonEmissionNode;
  const ancestors = [];
  while (curr) {
    ancestors.push({
      type: curr.constructor ? curr.constructor.name : null,
      enabled: curr.enabledProperty ? curr.enabledProperty.value : null,
      listeners: curr._inputListeners ? curr._inputListeners.length : null,
      phetioID: curr.phetioID || null
    });
    curr = curr.parent;
  }

  return {
    found: true,
    ancestors
  };
});
