const tabId = 1148881640;

const decayExecution = await browserjs(tabId, () => {
  const s1 = window.phet.joist.sim.screens[1];

  // Find the proton emission button
  let protonEmissionNode = null;
  const search = (node) => {
    if (!node) return;
    if (node.stringProperty && node.stringProperty.value.includes('Proton emission')) {
      protonEmissionNode = node;
      return;
    }
    if (node.children) {
      for (let c of node.children) {
        search(c);
        if (protonEmissionNode) return;
      }
    }
  };
  search(s1.view);

  const btn = protonEmissionNode.parent.parent.parent;

  const stateBefore = {
    protons: s1.model.particleAtom.protonCountProperty.value,
    neutrons: s1.model.particleAtom.neutronCountProperty.value,
    mass: s1.model.particleAtom.massNumberProperty.value,
    isStable: s1.model.isStableProperty.value,
    outgoing: s1.model.outgoingParticles.length
  };

  // Fire proton emission
  btn.pushButtonModel.fire();

  return { stateBefore };
});

console.log("State before decay:", JSON.stringify(decayExecution, null, 2));

// Step the simulation forward or wait a little for animation
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

const decayResults = await browserjs(tabId, () => {
  const s1 = window.phet.joist.sim.screens[1];

  // Let's get text displayed on screen
  const texts = [];
  const search = (node) => {
    if (!node) return;
    if (node.stringProperty) {
      texts.push({ str: node.stringProperty.value, visible: node.visible });
    }
    if (node.children) {
      node.children.forEach(search);
    }
  };
  search(s1.view);

  const outgoing = s1.model.outgoingParticles.map(p => ({
    type: p.type,
    position: [p.positionProperty.value.x, p.positionProperty.value.y]
  }));

  return {
    stateAfter: {
      protons: s1.model.particleAtom.protonCountProperty.value,
      neutrons: s1.model.particleAtom.neutronCountProperty.value,
      mass: s1.model.particleAtom.massNumberProperty.value,
      isStable: s1.model.isStableProperty.value,
      halfLife: s1.model.halfLifeNumberProperty.value,
      outgoing
    },
    visibleTexts: texts.filter(t => t.visible && (t.str.includes('Lithium') || t.str.includes('Beryllium') || t.str.includes('Li') || t.str.includes('Be') || t.str.includes('Proton') || t.str.includes('Neutron') || t.str.includes('Unstable') || t.str.includes('s') || t.str.includes('Half-life')))
  };
});

console.log("Decay result:", JSON.stringify(decayResults, null, 2));

const todoPath = "tmp://sessions/channel%3Apanel%3A17d5b494-1354-4833-84e9-0ef3e18e52ed/TODO.md";
await edit({
